import {LEVELS,MAPS} from '/games/tower-defense/src/freebuild/levels.js';
import {createOnlineClient} from './online-client.js';
const client=createOnlineClient(),$=id=>document.getElementById(id);
function table(parent,headers,rows){parent.replaceChildren();const t=document.createElement('table'),head=document.createElement('tr');for(const text of headers){const th=document.createElement('th');th.textContent=text;head.append(th);}t.append(head);for(const values of rows){const tr=document.createElement('tr');for(const v of values){const td=document.createElement('td');td.textContent=String(v??'');tr.append(td);}t.append(tr);}parent.append(t);}
async function request(path,payload){const response=await client.requestCompanion(new URL(`./api/admin/${path}`,import.meta.url),{method:payload?'POST':'GET',headers:{'Content-Type':'application/json'},...(payload?{body:JSON.stringify(payload)}:{})});const data=await response.json();if(!response.ok||!data.success)throw Error(data.message||'读取失败');return data;}
async function refresh(){const b=$('refresh');b.disabled=true;$('status').textContent=' 正在读取…';try{const data=await request('monitor');$('monitor-content').hidden=false;$('monitor-gate').hidden=true;$('overview').replaceChildren();for(const[label,value]of [['在线会话',data.current.online],['正在游玩',data.current.playing],['内存 MiB',(data.resources.rss/1048576).toFixed(1)],['服务运行小时',(data.resources.uptime_seconds/3600).toFixed(1)]]){const item=document.createElement('div'),n=document.createElement('strong');n.textContent=value;item.append(n,document.createTextNode(label));$('overview').append(item);}
table($('samples'),['时间','游戏','在线','游玩','采样内存 MiB'],data.minutes.slice(0,240).map(r=>[new Date(r.minute*60000).toLocaleString(),r.game,r.online,r.playing,(r.rss/1048576).toFixed(1)]));
table($('daily'),['日期','游戏','在线峰值','游玩峰值','采样次数'],data.daily.map(r=>[new Date(r.day*86400000).toISOString().slice(0,10),r.game,r.peak_online,r.peak_playing,r.samples]));
table($('totals'),['游戏','事件','记录数'],data.totals.map(r=>[r.game,r.kind,r.count]));
renderTower(data.tower);
table($('events'),['时间','游戏','对局标识','事件','角色 / 难度','属性与选择'],data.events.map(r=>[new Date(r.created).toLocaleString(),r.game,r.run_key.slice(0,12),r.kind,`${r.summary.hero||''} / ${r.summary.difficulty||''}`,JSON.stringify(r.summary)]));$('status').textContent=` 更新于 ${new Date().toLocaleTimeString()}`;
}catch(e){$('status').textContent=e.message;$('monitor-gate').textContent='需要管理员权限。';}finally{b.disabled=false;}}
$('refresh').onclick=refresh;
$('review').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target),input=Object.fromEntries(form);input.user_id=Number(input.user_id);input.quota=500000;if(!confirm(`确认对账户 ${input.user_id} 的 $1 订单 ${input.request_id} 执行「${input.decision}」复核？请先核对真实流水。`))return;try{await request('supporter-review',input);$('review-status').textContent='复核完成，未再次扣款。';}catch(e){$('review-status').textContent=e.message;}};
void refresh();

let towerReport=null;
function drawTowerHeatmap(){if(!towerReport)return;const stage=Number($('tower-stage').value),type=$('tower-type').value,difficulty=$('tower-difficulty').value,map=MAPS[LEVELS[stage-1].map],c=$('tower-heatmap').getContext('2d'),scale=.8;c.fillStyle='#dce6cc';c.fillRect(0,0,1280,800);c.save();c.scale(scale,scale);c.strokeStyle='#dbc59a';c.lineWidth=110;c.lineJoin='round';c.lineCap='round';for(const r of map.routes){c.beginPath();r.points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.stroke();}
const versions=towerReport.deployments.filter(r=>r.stage===stage&&r.difficulty===difficulty).map(r=>r.balance),version=Math.max(0,...versions),rows=towerReport.deployments.filter(r=>r.stage===stage&&r.difficulty===difficulty&&r.balance===version&&(!type||r.type===type)),max=Math.max(1,...rows.map(r=>r.builds));let count=0;for(const row of rows){const size={glm:2,kimi:3,whale:4,qwen:3}[row.type];c.fillStyle='rgba(210,61,38,'+(.15+.7*row.builds/max)+')';c.fillRect(row.cell_x*25,row.cell_y*25,size*25,size*25);count+=row.builds;}c.restore();$('tower-count').textContent='数值版本 '+version+' · '+count+' 次部署；颜色越深表示该位置使用越多。';}
function renderTower(data){towerReport=data;if(!data)return;
table($('tower-stages'),['版本','难度','关卡','对局','胜','负','中途重开','未完成','平均耗时秒','平均到达波'],data.stages.map(r=>[r.balance,({easy:'简单',normal:'普通',hard:'困难'}[r.difficulty]||r.difficulty),r.stage,r.runs,r.wins||0,r.losses||0,r.abandoned||0,r.unfinished,r.avg_seconds,r.avg_wave]));
table($('tower-economy'),['版本','难度','关卡','波','样本局数','平均金币','最低','最高','平均累计支出','平均剩余生命'],data.economy.map(r=>[r.balance,({easy:'简单',normal:'普通',hard:'困难'}[r.difficulty]||r.difficulty),r.stage,r.wave,r.runs,r.avg_gold,r.min_gold,r.max_gold,r.avg_spent,r.avg_lives]));
table($('tower-pressure'),['版本','难度','关卡','波','样本局数','峰值敌人数','峰值剩余HP','峰值末段威胁','末25%敌人数峰值','平均扣血','路线1最远%','路线2最远%'],data.pressure.map(r=>[r.balance,({easy:'简单',normal:'普通',hard:'困难'}[r.difficulty]||r.difficulty),r.stage,r.wave,r.runs,r.avg_peak_alive,r.avg_peak_hp,r.avg_peak_threat,r.avg_peak_late,r.avg_base_lost,r.route_0_percent,r.route_1_percent]));
table($('tower-upgrades'),['版本','难度','关卡','塔','方向','等级','选择次数'],data.upgrades.map(r=>[r.balance,({easy:'简单',normal:'普通',hard:'困难'}[r.difficulty]||r.difficulty),r.stage,r.type,r.branch||'基础',r.level,r.selections]));drawTowerHeatmap();}
$('tower-stage').onchange=$('tower-type').onchange=$('tower-difficulty').onchange=drawTowerHeatmap;
$('tower-export').onclick=()=>{if(!towerReport)return;const url=URL.createObjectURL(new Blob([JSON.stringify(towerReport,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='tower-analysis-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
